//! Zoom on a window that is already drawn: `src/rescale.rs` itself, on the app's own window and the same software
//! renderer, into a frame of the window's unchanged pixels. A scale given alone stopped the program in the renderer,
//! in every system's account check, at the first zoom.
#![allow(clippy::expect_used, clippy::unwrap_used, reason = "a test that cannot draw must fail")]

#[allow(clippy::all, clippy::pedantic, clippy::nursery, clippy::restriction, reason = "code generated by Slint")]
mod ui {
    slint::include_modules!();
}
#[path = "../src/rescale.rs"]
mod rescale;

use slint::{
    ComponentHandle, PhysicalSize,
    platform::{
        Platform, WindowAdapter,
        software_renderer::{MinimalSoftwareWindow, PremultipliedRgbaColor, RepaintBufferType},
    },
};
use std::rc::Rc;

struct Headless(Rc<MinimalSoftwareWindow>);

impl Platform for Headless {
    fn create_window_adapter(&self) -> Result<Rc<dyn WindowAdapter>, slint::PlatformError> {
        Ok(self.0.clone())
    }
}

const WIDTH: u32 = 1200;
const HEIGHT: u32 = 800;

/// Draws the window into a frame of its pixels, as the window's own buffer is.
fn draw(window: &MinimalSoftwareWindow) {
    window.request_redraw();
    let wide = usize::try_from(WIDTH).unwrap();
    let mut pixels = vec![PremultipliedRgbaColor::default(); wide * usize::try_from(HEIGHT).unwrap()];
    window.draw_if_needed(|renderer| {
        renderer.render(&mut pixels, wide);
    });
}

#[test]
fn zooming_a_drawn_window_keeps_it_within_its_pixels() {
    let window = MinimalSoftwareWindow::new(RepaintBufferType::NewBuffer);
    slint::platform::set_platform(Box::new(Headless(window.clone()))).unwrap();
    let app = ui::App::new().unwrap();
    app.show().unwrap();
    window.set_size(PhysicalSize::new(WIDTH, HEIGHT));
    draw(&window);
    // In, further in, out past where it began, and back: each drawn into the same pixels.
    for scale in [1.25_f32, 1.5, 2.0, 0.9, 1.0] {
        rescale::rescale(app.window(), scale);
        assert!((app.window().scale_factor() - scale).abs() < f32::EPSILON);
        assert_eq!(app.window().size(), PhysicalSize::new(WIDTH, HEIGHT), "zoom must not resize the window");
        let points = app.window().size().to_logical(scale);
        assert!((points.width - 1200.0 / scale).abs() < 0.5, "at {scale} the window is {} points wide", points.width);
        draw(&window);
    }
}
